                writer.WriteString("sUserName", ezsigntemplatepackagesignerResponse.SUserName);

            if (ezsigntemplatepackagesignerResponse.SUsergroupNameXOption.IsSet)
                writer.WriteString("sUsergroupNameX", ezsigntemplatepackagesignerResponse.SUsergroupNameX);
        }
    }
